parameters.command:
cat > /tmp/plan.json << 'EOF'
{
  "ops": [
    {
      "op": "add-node",
      "id": "loadCatalog",
      "type": "core.action.script",
      "definitionFile": "/tmp/script.json",
      "label": "Load Catalog",
      "inputs": {
        "script": "return { catalog: [{\"title\":\"Linear Algebra Done Right\",\"author\":\"Axler\",\"field\":\"math\",\"difficulty\":6,\"pages\":340},{\"title\":\"Deep Learning\",\"author\":\"Goodfellow\",\"field\":\"ml\",\"difficulty\":9,\"pages\":800},{\"title\":\"Statistical Learning\",\"author\":\"James\",\"field\":\"data science\",\"difficulty\":4,\"pages\":440},{\"title\":\"Elements of Statistical Learning\",\"author\":\"Hastie\",\"field\":\"stats\",\"difficulty\":9,\"pages\":745},{\"title\":\"Bayesian Data Analysis\",\"author\":\"Gelman\",\"field\":\"stats\",\"difficulty\":8,\"pages\":580},{\"title\":\"Python for Data Analysis\",\"author\":\"McKinney\",\"field\":\"data science\",\"difficulty\":3,\"pages\":550},{\"title\":\"Probability Theory\",\"author\":\"Jaynes\",\"field\":\"math\",\"difficulty\":10,\"pages\":753},{\"title\":\"Information Theory\",\"author\":\"MacKay\",\"field\":\"ml\",\"difficulty\":7,\"pages\":540}] };"
      }
    },
    {
      "op": "add-node",
      "id": "curateReadingList",
      "type": "core.action.transform",
      "definitionFile": "/tmp/transform.json",
      "label": "Curate Reading List",
      "inputs": {
        "collection": "$vars.loadCatalog.output.catalog",
        "operations": [
          {
            "id": "op1",
            "type": "filter",
            "config": {
              "operation": "and",
              "filters": [
                { "id": "f1", "field": "difficulty", "condition": "greater_than", "value": 5 },
                { "id": "f2", "field": "pages", "condition": "less_than", "value": 600 }
              ]
            }
          },
          {
            "id": "op2",
            "type": "map",
            "config": {
              "keepOriginalFields": false,
              "mappings": [
                { "id": "m1", "field": "title", "transformation": "uppercase", "renameTo": "" },
                { "id": "m2", "field": "author", "transformation": "copy", "renameTo": "" }
              ]
            }
          }
        ]
      }
    },
    {
      "op": "add-node",
      "id": "end",
      "type": "core.control.end",
      "definitionFile": "/tmp/end.json",
      "label": "End",
      "outputs": "none"
    },
    {
      "op": "add-edge",
      "source": "start",
      "sourcePort": "output",
      "target": "loadCatalog",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "loadCatalog",
      "sourcePort": "success",
      "target": "curateReadingList",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "curateReadingList",
      "sourcePort": "output",
      "target": "end",
      "targetPort": "input"
    },
    {
      "op": "add-variable",
      "id": "readingList",
      "direction": "out",
      "type": "array",
      "description": "Curated reading list with uppercased title and author"
    },
    {
      "op": "add-output-mapping",
      "endNode": "end",
      "var": "readingList",
      "source": "=js:$vars.curateReadingList.output"
    }
  ]
}
EOF
